"""Write the RL owner's final local readout from settled, immutable evidence."""
from pathlib import Path
import datetime,json
from .launch import CAMPAIGN
from .report import collect
from simulators.clash.autoresearch.common import ROOT,dump,sha

def write():
 root=CAMPAIGN/'clash/rl';cost=collect();analysis=json.loads((root/'fresh-assessment/analysis.json').read_text());selection=json.loads((root/'selection-close.json').read_text())
 cleanup=sorted(root.glob('cleanup-*.json'))[-1];closed=json.loads(cleanup.read_text())
 if not closed['all_stopped_zero_tasks'] or cost['held']['gpu_seconds']:raise ValueError('Finish owned provider cleanup and GPU reconciliation first')
 training=[];development=[]
 for attempt in cost['attempts']:
  folder=root/attempt['name'];top=folder/'collected/result.json'
  if top.exists():
   value=json.loads(top.read_text())
   for case,item in value.get('cases',{}).items():
    result=item['result'];training.append({'attempt':attempt['name'],'training_seed':value['seed'],'case':case,'case_process_seconds':item['case_process_seconds'],**{k:result.get(k) for k in ('updates','samples','natural_games','optimizer_steps','teacher_updates','ppo_only_updates','learned_neural_opponent_decisions','demo_decisions','demo_natural_games','visible_refusal_nonzero_decisions','parameters','proof')}})
  for path in sorted(folder.glob('*-development/result.json')):
   v=json.loads(path.read_text());development.append({'attempt':attempt['name'],'stage_alias':path.parent.name.removesuffix('-development'),**{k:v[k] for k in ('complete','games','mean_points','by_opponent')}})
 authorization=CAMPAIGN/'authorization.json'
 value={'status':'complete-bounded-reference-campaign','updated_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'authorization_sha256':sha(authorization),'scope':'Clash RL reference owner only; no engine/rules/evaluator/root-tool edits, commits, push or publication','assessment':analysis,'selected_candidates':selection['candidates'],'selection':{'receipt':str(root/'selection-close.json'),'development_receipt':str(root/'selection-development.json'),'bank_commitment':json.loads((root/'fresh-assessment/commitment.json').read_text())['bank_sha256'],'fresh_engine_units':32,'both_seats':True,'opponents':['standard','pressure','teacher','retained-deepseek','intermediate'],'no_policy_tuning_after_closure':True},'training':training,'public_development':development,'cost':{k:v for k,v in cost.items() if k not in ('attempts','resource_operations')},'attempts':[{k:v for k,v in a.items() if not k.startswith('collected/')} for a in cost['attempts']],'provider_cleanup':{'receipt':str(cleanup),'all_stopped_zero_tasks':closed['all_stopped_zero_tasks'],'apps':closed['apps'],'volumes_retained':True},'checks':{'local_tests':(root/'tests-final.log').read_text().strip().splitlines()[-1],'gpu_resume_and_export_receipts':[str(p) for p in sorted(root.glob('paired-*/artifact-validation.json'))],'selected_weights_verified_inside_complete_checkpoint':True},'limitations':['Fixed8 native task; independent commercial-game fidelity and human/expert calibration are unverified.','Only two precommitted corrected MLP training seeds and one conditional spatial paired pilot; bootstrap intervals are exploratory with limited training replication.','The selected corrected MLP early stage contains PPO with auxiliary teacher assistance and no subsequent PPO-only updates; later PPO-only results remain retained. Early teacher-assisted inference milestones are weights-only exports; complete later checkpoints retain those exact tensors in frozen history. They are not earlier optimizer/world resume points.','Exploratory v1/v2 lightweight curriculum used wrong public-coordinate lane/half thresholds. Those sources, costs, failures and checkpoints remain retained; v3/v4 use exact pinned public scripts.','Some paired-run settlement sidecars initially looked only at the single-proof output path and recorded result_present=false. Paired result files and independent source/world/tensor validation establish completion; original sidecars remain retained.','Training counters report logical trajectories; the exact-resume audit executes one extra discarded learner update per successful case. Full provider allocations include it.','Training source recorded request-refusal field62; delayed-run field63 was separately instrumented only in the final assessment. No retrospective zero is inferred.','Resource totals include conservative unresolved CPU image-build, observer and storage holds; they are not a provider invoice.'],'normalization':{'strong_panel_qualified':False,'superhuman_evidence':False,'reference_normalized_score':None}}
 out=ROOT/'reports/clash/selfplay-reference-2026-11-09';dump(out.with_suffix('.json'),value)
 lines=['# Clash self-play reference — November 9, 2026','','The bounded campaign completed with trained, admitted stateless neural artifacts, matched controls, exact GPU resume checks and a fresh frozen assessment. The policies remain weak against serious scripted opposition. Human/superhuman strength and reference normalization remain unqualified.','','## Fresh assessment','','Training and selection closed before generating the 32-unit private engine bank. Each selected candidate played both seats against five frozen opponents in isolated CPU policy processes. No policy tuning followed opening the bank.','', '| Family | Training seeds | Selected stage | Games | Panel points /100 |','|---|---|---|---:|---:|']
 for name,f in analysis['families'].items():lines.append(f"| {name} | {', '.join(map(str,f['training_seeds']))} | {f['stage']} | {f['games']} | {f['mean_points_0_100']:.3f} |")
 lines+=['','These are points on a fixed public-opponent panel, not expert win rates. All required games completed naturally; illegal actions, caps, simulator faults and infrastructure failures invalidate an assessment rather than being converted to losses. Public request and delayed-run refusal observations are counted separately in the JSON readout.','','| Paired comparison | Delta points | 95% interval | Training replicates |','|---|---:|---|---:|']
 for name,c in analysis['paired_comparisons'].items():lines.append(f"| {name} | {c['mean_delta_points']:.3f} | [{c['interval95'][0]:.3f}, {c['interval95'][1]:.3f}] | {c['training_replicates']} |")
 lines+=['',f"Corrected MLP learned-reference improvement criterion: **{analysis['learned_reference_improvement_qualified']}**. Spatial pilot conditional criterion: **{analysis.get('spatial-learned_reference_improvement_qualified',False)}**. Qualification requires both paired lower endpoints above zero. The MLP intervals resample training seeds and paired engine units; the spatial comparison has only one training seed and is conditional on that seed. Neither supports a general strong-play claim.",'','## What was trained','','The exact fixed8 native task keeps 7,024 public observation integers, all 200 entity rows, 2,307 masked actions and the natural horizon. PPO uses alternating learner seats, episode-fixed pinned standard/pressure/intermediate/teacher opponents, and frozen neural history selected through smoothed PFSP. Demonstrations come from separate expert trajectories; their outcomes never count as PPO wins or rewards. Teacher assistance ends after 192 updates in the corrected recipes, followed by pure PPO.','','The corrected entity/card MLP has 381,902 parameters; its two precommitted seeds are 49192 and 69193 with opposite case order. The one permitted 151,439-parameter spatial pilot uses a Gaussian public-entity raster on the verified 18×32 action grid and a small CNN. It was conditional on the MLP weakness gate and is not replicated. Each paired case has the same 832.5-second process cap on the same H100/32-physical-core/128-GiB allocation. The control skips imitation work and can therefore complete more PPO updates.','','The development-selected MLP teacher checkpoint is earlier than its full final checkpoint: further pure PPO regressed development strength. Selection uses one stage per family across all seeds, retaining every seed and all negative results. Inference milestones preserve exact trained tensors; the complete final checkpoint contains the selected earlier tensors in frozen history. Resuming an earlier inference milestone with a later optimizer/world state is not supported.','','| Attempt / case | Updates | Assisted / pure PPO | Learner rows | Natural learner games | Learned-history decisions |','|---|---:|---:|---:|---:|']
 for t in training:lines.append(f"| {t['attempt']} / {t['case']} | {t['updates']} | {t['teacher_updates']} / {t['ppo_only_updates']} | {t['samples']} | {t['natural_games']} | {t['learned_neural_opponent_decisions']} |")
 lines+=['','Logical counters exclude one extra discarded update used for the exact-resume replay audit. Each paired case executes 2,048 extra learner rows and eight extra optimizer steps for this audit; the initial proof executes 4,096 rows/eight steps. Full allocation accounting includes this work. Demonstration rows and games are separately listed in JSON.','','## Artifacts and validation','','Each selected source and weight bundle passes the canonical direct-greedy neural admission. The derived head preserves weights and compiles card-marginal/tile-max decoding into a direct flat argmax. Its softmax is not the original PPO sampling distribution. All complete checkpoints bind source, rules/data, native compiler/build/runtime, optimizer, CPU/CUDA RNG, live worlds/output buffers, demonstration worlds, episode assignments and frozen league identities. Actual GPU next-update replay passed; downloaded world payload checksums and final NPZ tensor bytes were independently verified.','',f"Local checks: `{value['checks']['local_tests']}`.",'','Selected bundles and full resume checkpoints are enumerated in the JSON readout and in `evidence/reference-readiness-20261109-0251Z/clash/rl/selection-close.json`. The immutable selection, bank commitment, raw per-game results, source archives, all failures and exact provider receipts remain under that ignored campaign directory. The private bank is not copied into this report.','','Reproduce local correctness checks:','.venv-clash/bin/python -m pytest simulators/clash/reference_training/tests -q','','Inspect costs without starting workers:','.venv-clash-ar/bin/python -m simulators.clash.reference_training.report','','All launch and recovery paths reject a closed selection. No further training expansion is authorized by this readout.','','## Costs and cleanup','',f"RL role GPU time: **{cost['settled']['gpu_seconds']:.3f} seconds** ({cost['settled']['gpu_seconds']/60:.3f} minutes); remaining GPU hold: {cost['held']['gpu_seconds']:.0f} seconds. Resources: **${cost['settled']['resources_usd']:.6f} settled + ${cost['held']['resources_usd']:.6f} conservative holds = ${cost['role_use']['resource_usd']:.6f}**. External model calls: zero / $0. The role remains within its 12,600-second/$32/$2.50 subcaps and the immutable shared campaign ledger; evaluator resources are separate. CPU builds/observers, failed attempts, full GPU idle/setup time and storage margin remain included. These totals are not invoice-verified.",'',f"Cleanup verified **{len(closed['apps'])} owned apps stopped with zero running tasks**. Only this RL owner's explicitly recorded apps were stopped. Private Volumes and checkpoints remain retained; unresolved build/observer/storage charges remain held.",'','## Limits and negative evidence','','The initial proof established functioning learning and resume/export machinery but scored 1.5625/100 on its public development panel. Exploratory v2 also failed to establish improvement and used incorrect lightweight-curriculum lane/half thresholds. These immutable attempts remain charged and retained. Corrected v3/v4 use the pinned canonical public opponents. Development teacher agreement improved while serious opponent strength remained poor; more PPO often erased early gains.','','[ClashRoyaleAi](https://github.com/itzik123/ClashRoyaleAi) releases and learning source were audited. None of the 13 inspected releases supplied downloadable assets. Its recurrent 1,846,963-parameter, 13,977-int/612-cell interface is incompatible here. Only curriculum/league ideas were adapted; no upstream weights, engine assumptions, elixir handicaps or inference search were imported.','','Training records request-refusal field62; final assessment also observes delayed-run field63. The counters measure nonzero-code decisions, not unique rejection events. Historical absence of field63 instrumentation is not evidence of zero delayed refusals.','','No engine/rules/evaluator/root-tool edits, commit, push or publication were performed by this owner.']
 out.with_suffix('.md').write_text('\n'.join(lines)+'\n');return {'report':str(out.with_suffix('.md')),'gpu_seconds':cost['settled']['gpu_seconds'],'resource_usd_including_holds':cost['role_use']['resource_usd']}

if __name__=='__main__':print(json.dumps(write(),indent=2))
